65	export async function importModule(
66	  path: string,
67	  { skipCache = false }: { skipCache?: boolean } = {}
68	) {
69	  if (!isTypescriptLoaderRegistered) {
70	    const typescriptLoaderUrl = importMetaResolve('storybook/internal/bin/loader');
71	    register(typescriptLoaderUrl, import.meta.url);
72	    isTypescriptLoaderRegistered = true;
73	  }
74	
75	  let mod;
76	  try {
77	    const resolvedPath = win32.isAbsolute(path) ? pathToFileURL(path).href : path;
78	    // When applicable, add a hash to the import URL to bypass cache
79	    const importUrl = skipCache ? `${resolvedPath}?${Date.now()}` : resolvedPath;
80	    mod = await import(importUrl);
81	  } catch (importError) {
82	    try {
83	      // fallback to require to support older behavior
84	      // this is relevant for presets that are only available with the "require" condition in a package's export map
85	      const require = createRequire(import.meta.url);
86	      if (skipCache) {
87	        delete require.cache[require.resolve(path)];
88	      }
89	      mod = require(path);
90	    } catch (requireError) {
91	      /*
92	        If everything fails, throw the original import error, as the require error won't be helpful
93	        in Node 20 requireError will always be "Error [ERR_REQUIRE_CYCLE_MODULE]: Cannot require() ES Module"
94	        in Node 22 requireError will always be "Error [ERR_INTERNAL_ASSERTION]: Unexpected module status 5. Cannot require() ES Module"
95	      */
96	      throw importError;
97	    }
98	  }
99	  return mod.default ?? mod;
100	}
