126	export const safeResolveModule = ({
127	  specifier,
128	  parent,
129	  extensions = ['.mjs', '.js', '.cjs'],
130	}: {
131	  specifier: string;
132	  parent?: string;
133	  extensions?: string[];
134	}) => {
135	  try {
136	    const resolvedPath = resolveModulePath(specifier, {
137	      from: parent,
138	      extensions: [''].concat(extensions),
139	    });
140	    if (statSync(resolvedPath).isFile()) {
141	      return resolvedPath;
142	    }
143	  } catch (e: any) {}
144	};
