1	import type { ErrorCategory } from '../../../shared/utils/categorize-render-errors.ts';
2	import { categorizeError } from '../../../shared/utils/categorize-render-errors.ts';
3	import {
4	  type ErrorCategorizationResult,
5	  type StoryTestResult,
6	  type TestRunSummary,
7	} from './types.ts';
8	
9	/**
10	 * For a given list of test results:
11	 *
12	 * - Go through failures
13	 * - Categorize errors into categories
14	 * - Return structured data about the run, with categorized errors instead of the actual error
15	 *   messages
16	 */
17	function extractCategorizedErrors(testResults: StoryTestResult[]): ErrorCategorizationResult {
18	  const failed = testResults.filter((r) => r.status === 'FAIL' && r.error);
19	
20	  // Map: category -> { count, uniqueErrors: Set<string>, matchedDependencies }
21	  const map = new Map<
22	    ErrorCategory,
23	    { count: number; uniqueErrors: Set<string>; matchedDependencies: Set<string> }
24	  >();
25	
26	  // To count unique error messages (by their message, not by category)
27	  const uniqueErrorMessages = new Set<string>();
28	
29	  for (const r of failed) {
30	    const { category, matchedDependencies } = categorizeError(r.error!, r.stack);
31	
32	    if (!map.has(category)) {
33	      map.set(category, { count: 0, uniqueErrors: new Set(), matchedDependencies: new Set() });
34	    }
35	
36	    const data = map.get(category)!;
37	    data.count++;
38	    matchedDependencies.forEach((dep) => data.matchedDependencies.add(dep));
39	
40	    // Use the full error message for unique error message counting
41	    uniqueErrorMessages.add(r.error!);
42	    data.uniqueErrors.add(r.error!);
43	  }
44	
45	  const categorizedErrors = Array.from(map.entries()).reduce<Record<string, any>>(
46	    (acc, [category, data]) => {
47	      acc[category] = {
48	        uniqueCount: data.uniqueErrors.size,
49	        count: data.count,
50	        matchedDependencies: Array.from(data.matchedDependencies).sort(),
51	      };
52	      return acc;
53	    },
54	    {}
55	  );
56	
57	  return {
58	    totalErrors: failed.length,
59	    uniqueErrorCount: uniqueErrorMessages.size,
60	    categorizedErrors,
61	  };
62	}
