64	/** Transform the Vitest test results to our expected format and return a TestRunSummary */
65	export function parseVitestResults(report: any): TestRunSummary {
66	  // Transform the Vitest test results to our expected format
67	  const storyTestResults: StoryTestResult[] = [];
68	  let passedButEmptyRender = 0;
69	
70	  for (const testSuite of report.testResults) {
71	    for (const assertion of testSuite.assertionResults) {
72	      const storyId = assertion.meta?.storyId || assertion.fullName;
73	
74	      const status =
75	        assertion.status === 'passed' ? 'PASS' : assertion.status === 'failed' ? 'FAIL' : 'PENDING';
76	
77	      // Check for empty render in reports
78	      const hasEmptyRender = assertion.meta?.reports?.some(
79	        (report: { type: string; result?: { emptyRender?: boolean } }) =>
80	          report.type === 'render-analysis' && report.result?.emptyRender === true
81	      );
82	
83	      if (status === 'PASS' && hasEmptyRender) {
84	        passedButEmptyRender++;
85	      }
86	
87	      // Extract error message (first line of failureMessages)
88	      let error: string | undefined;
89	      let stack: string | undefined;
90	      if (assertion.failureMessages && assertion.failureMessages.length > 0) {
91	        stack = assertion.failureMessages[0];
92	        error = stack?.split('\n')[0]; // Take only the first line
93	      }
94	
95	      storyTestResults.push({
96	        storyId,
97	        status,
98	        error,
99	        stack,
100	      });
101	    }
102	  }
103	
104	  const total = report.numTotalTests;
105	  const passed = report.numPassedTests;
106	  const successRate = total > 0 ? parseFloat((passed / total).toFixed(2)) : 0;
107	  const successRateWithoutEmptyRender =
108	    total > 0 ? parseFloat(((passed - passedButEmptyRender) / total).toFixed(2)) : 0;
109	
110	  // Extract and categorize unique errors
111	  const errorClassification = extractCategorizedErrors(storyTestResults);
112	  const categorizedErrors = errorClassification.categorizedErrors;
113	
114	  return {
115	    summary: {
116	      total,
117	      passed,
118	      passedButEmptyRender,
119	      successRate,
120	      successRateWithoutEmptyRender,
121	      uniqueErrorCount: errorClassification.uniqueErrorCount,
122	      categorizedErrors,
123	    },
124	  };
