// Matches ANSI escape sequences (e.g. color codes) that Storybook adds to error output.
const ANSI_ESCAPE_REGEX = /\x1B\[[0-9;]*m/g;

// Matches the "Click to debug ..." banner that the Storybook Vitest addon prepends to errors.
const DEBUG_BANNER_REGEX = /Click to debug the error directly in Storybook:.*/gi;

/** Strip ANSI codes and Storybook debug banners from a raw error string. */
function stripDebugBanner(input: string): string {
  return input.replace(ANSI_ESCAPE_REGEX, '').replace(DEBUG_BANNER_REGEX, '');
}

/** Return the first non-empty (trimmed) line of a string, or undefined if there is none. */
function firstNonEmptyLine(input: string): string | undefined {
  for (const line of input.split('\n')) {
    const trimmed = line.trim();
    if (trimmed.length > 0) {
      return trimmed;
    }
  }
  return undefined;
}

/**
 * Extract a concise, human-readable error message from a raw error message and/or stack trace.
 *
 * - Storybook debug banners are stripped from both message and stack.
 * - Returns the first non-empty line of the cleaned message.
 * - Falls back to the first non-empty line of the stack trace when the message is empty.
 * - Returns 'unknown error' when neither yields anything useful.
 */
export function extractErrorMessage(
  message: string | undefined,
  stack: string | undefined
): string {
  const cleanedMessage = message ? stripDebugBanner(message) : '';
  const messageLine = firstNonEmptyLine(cleanedMessage);
  if (messageLine) {
    return messageLine;
  }

  const cleanedStack = stack ? stripDebugBanner(stack) : '';
  const stackLine = firstNonEmptyLine(cleanedStack);
  if (stackLine) {
    return stackLine;
  }

  return 'unknown error';
}

/**
 * Detect whether any report indicates that the story rendered nothing.
 *
 * Returns true if any report is a 'render-analysis' report whose `result.emptyRender` is true.
 */
export function detectEmptyRender(
  reports: readonly { type: string; result?: unknown }[] | undefined
): boolean {
  if (!reports) {
    return false;
  }

  return reports.some(
    (report) =>
      report.type === 'render-analysis' &&
      (report.result as { emptyRender?: boolean } | undefined)?.emptyRender === true
  );
}

/** Normalize a raw status string into one of 'PASS', 'FAIL', or 'PENDING'. */
function normalizeStatus(statusRaw: string | undefined): StoryTestStatus {
  const normalized = (statusRaw ?? '').toLowerCase();
  if (normalized.startsWith('pass')) {
    return 'PASS';
  }
  if (normalized.startsWith('fail')) {
    return 'FAIL';
  }
  return 'PENDING';
}

