 * - Normalizes the raw status to 'PASS', 'FAIL', or 'PENDING'.
 * - Marks `emptyRender` as true only when the status is PASS and an empty render was detected.
 * - Extracts the error message and stack from the first error object.
 */
export function toStoryTestResult(input: {
  storyId: string | undefined;
  statusRaw: string | undefined;
  errors?: readonly { message?: string; stack?: string }[];
  reports?: readonly { type: string; result?: unknown }[];
